  Stop             = "entire hooks codex stop"
  PostToolUse      = "entire hooks codex post-tool-use"
}

foreach ($event in $commands.Keys) {
  foreach ($group in $json.hooks.$event) {
    foreach ($hook in $group.hooks) {
      if ($hook.command -like "*entire hooks codex*") {
        $hook.command = $commands[$event]
      }
    }
  }
}

